import frontmatter from 'front-matter';
import * as fs from 'fs/promises';
import * as path from 'path';
import { chokidarGlob } from './chokidarGlob';
import { logAndExit } from './logAndExit';
import { DB, ModuleMetaObject } from './types';

/**
 * @internal
 */
export const getDeepDependencies = (
  db: DB,
): Record<string, Record<string, true>> => {
  const deps: Record<string, Record<string, true>> = {};

  const getDeepDepsOfEntry = (
    deps: string[],
    depSet = new Set<string>(),
    depth = 0,
  ) => {
    if (depth > 0) {
      deps.forEach((dep) => {
        depSet.add(dep);
      });
    }
    deps.forEach((dep) => {
      if (!db[dep]) {
        return;
      }
      getDeepDepsOfEntry(db[dep].deps, depSet, depth + 1);
    });
    return depSet;
  };

  Object.values(db).forEach((entry) => {
    const depSet = getDeepDepsOfEntry(entry.deps);

    deps[entry.name] = {};

    Array.from(depSet).forEach((dep) => {
      deps[entry.name][dep] = true;
    });
  });

  return deps;
};

const filterOutDeepDependencies = (db: DB): DB => {
  const deepDependencies = getDeepDependencies(db);

  Object.entries(db).forEach(([key, entry]) => {
    db[key].deps = entry.deps.filter((dep) => {
      return !deepDependencies[key]?.[dep];
    });
  });

  return db;
};

export const getContentGraph = async (glob: string) => {
  const allFiles = await chokidarGlob(glob);

  if (allFiles.length === 0) {
    logAndExit('No files found!');
  }

  const db: DB = {};

  for (const file of allFiles) {
    const fileContents = await fs.readFile(file, 'utf-8');

    const attributes = frontmatter(fileContents);
    const meta = ModuleMetaObject.parse(attributes.attributes);

    const name = path.parse(file).name;

    db[name] = {
      name,
      deps: meta.deps || [],
      body: attributes.body,
      meta,
    };
  }

  for (const node of Object.values(db)) {
    for (const dep of node.deps) {
      if (!db[dep]) {
        throw new Error(
          `Error in ${node.name}.md: ${dep} is not in the database`,
        );
      }
    }
  }

  return filterOutDeepDependencies(db);
};

import { execSync } from 'child_process';
import * as path from 'path';
import { writeFileSync } from 'fs';
import { getConfig } from './getConfig';
import { getContentGraph } from './getContentGraph';
import { chokidarGlob } from './chokidarGlob';

export const getDotfile = async (glob: string, cachePath: string) => {
  const db = await getContentGraph(glob);
  /**
   * Relative paths
   */
  const allFiles = await chokidarGlob(glob);

  const config = await getConfig();

  const getColor = (name: string) => {
    const group = config?.groups.find((g) => g.id === db[name].meta.group);
    if (!group) return 'black';
    return group.color;
  };

  /**
   * Full-length paths
   */
  let changedModulesFromGit: string[] = [];

  try {
    changedModulesFromGit = execSync('git diff --name-only HEAD', {
      cwd: process.cwd(),
    })
      .toString()
      .split('\n')
      .map((i) => i.trim())
      .filter(Boolean);
  } catch (e) {}

  /**
   * Relative paths
   */
  const allTrackedFiles = execSync('git ls-files', {
    cwd: process.cwd(),
  })
    .toString()
    .split('\n')
    .map((i) => i.trim())
    .filter(Boolean);

  const changedModulesSet = new Set<string>();

  allFiles.forEach((file) => {
    const fileIsTracked = allTrackedFiles.includes(file);

    if (!fileIsTracked) {
      changedModulesSet.add(path.parse(file).name);
    }

    const fileHasChanged = changedModulesFromGit.some((changedFile) => {
      return changedFile.includes(file);
    });

    if (fileHasChanged) {
      changedModulesSet.add(path.parse(file).name);
    }
  });

  const dotfileText = `
    digraph kmap {
      ${Object.values(db)
        .map((node) => {
          return `
          ${node.deps
            .map((dep) => {
              const secondColor = getColor(node.name);
              return `"${dep}" -> "${node.name}" ${`[color="${secondColor}"]`}`;
            })
            .join('\n')}`;
        })
        .join('\n')}
      ${Object.values(db)
        .map((item) => {
          return `"${item.name}" [color="${getColor(
            item.name,
          )}",penwidth=2.0, margin="0.2,0"]`;
        })
        .join('\n')}
      ${Array.from(changedModulesSet)
        .map((mod) => {
          return `"${mod}" [style="filled,bold" fontcolor="white" tooltip="Changed"]`;
        })
        .join('\n')}
    }
  `;

  const dotfilePath = path.resolve(cachePath, 'dotfile.dot');

  const imgPath = path.resolve(cachePath, 'graph.svg');

  writeFileSync(dotfilePath, dotfileText);

  execSync(`dot -Tsvg ${dotfilePath} > ${imgPath}`);

  return { dotfilePath, imgPath };
};

import { getDeepDependencies } from './getContentGraph';
import { Config, DB } from './types';

export const getPathTo = (db: DB, config: Config, element: string) => {
  return getPathToMany(db, config, [element]);
};

export const getPathToMany = (db: DB, config: Config, elements: string[]) => {
  const pathSegments: string[] = [];

  const deepDependencies = getDeepDependencies(db);

  Object.values(db).forEach((dbItem) => {
    dbItem.deps.forEach((dep) => {
      deepDependencies[dbItem.name][dep] = true;
    });
  });

  const getDescendents = (path: string) => {
    if (db[path]) {
      if (!pathSegments.some((segment) => segment === path)) {
        pathSegments.push(path);
        db[path].deps.forEach((dep) => {
          getDescendents(dep);
        });
      }
    }
  };

  elements.forEach((element) => {
    getDescendents(element);
  });

  const groupedPaths: Record<string, string[]> = {};

  pathSegments.forEach((segment) => {
    const group = db[segment].meta.group;

    if (group) {
      if (!groupedPaths[group]) {
        groupedPaths[group] = [];
      }
      groupedPaths[group].push(segment);
    }
  });

  return Object.entries(groupedPaths)
    .sort(([a], [b]) => {
      const aGroupIndex = config?.groups?.findIndex((g) => g.id === a) ?? 0;
      const bGroupIndex = config?.groups?.findIndex((g) => g.id === b) ?? 0;
      return aGroupIndex - bGroupIndex;
    })
    .flatMap(([, paths]) => {
      return paths.sort((a, b) => {
        if (deepDependencies[b][a]) {
          return -1;
        }
        return 1;
      });
    });
};

