export * from './getContentGraph';
export * from './getPathTo';
export * from './getConfig';

import express from 'express';
import { getDotfile } from './dotfile';
import * as path from 'path';
import * as fs from 'fs';
import { WebSocketServer, WebSocket } from 'ws';
import { watch } from 'chokidar';
import { CONFIG_FILE_PATH } from './constants';

export const startServer = async (
  glob: string,
  binPath: string,
  opts: { publicPath: string; port: number },
) => {
  const app = express();

  app.use(express.static(opts.publicPath));

  const dotfile = await getDotfile(glob, binPath);

  app.get('/', (req, res) => {
    res.send(getServerHtml(opts.port + 1));
  });
  app.get('/img.svg', (req, res) => {
    res.header('Content-Type', 'image/svg+xml');
    res.header('Content-Disposition', 'inline');

    res.status(200);

    res.send(fs.readFileSync(dotfile.imgPath));
  });
  app.get('/script.js', (req, res) => {
    res.send(fs.readFileSync(path.resolve(binPath, './devClient.js')));
  });

  const wss = new WebSocketServer({ port: opts.port + 1 });

  const connections = new Set<WebSocket>();

  wss.on('connection', (ws) => {
    connections.add(ws);
    ws.on('close', () => {
      connections.delete(ws);
    });
  });

  const handleChange = async () => {
    await getDotfile(glob, binPath);

    connections.forEach((ws) => {
      ws.send('New');
    });
  };

  watch([glob, CONFIG_FILE_PATH], { ignoreInitial: true })
    .on('change', handleChange)
    .on('add', handleChange)
    .on('unlink', handleChange);

  app.listen(opts.port, () => {
    console.log(`Listening on http://localhost:${opts.port}`);
  });
};

const getServerHtml = (port: number) => {
  return `
    <!DOCTYPE html>
    <html>
      <head>
        <meta charset="utf-8" />
        <meta name="viewport" content="width=device-width, initial-scale=1.0" />
        <title>Graph Docs</title>
      </head>
      <body>
        <object data="/img.svg" type="image/svg+xml" width="1900px" height="720px"></object>
        <script>
          const PORT = ${port};
        </script>
        <script src="/script.js"></script>
      </body>
    </html>
  `;
};

import * as fs from 'fs/promises';
import * as path from 'path';
import { CONFIG_FILE_PATH } from './constants';
import { ConfigObject } from './types';

export const getConfig = async () => {
  const configPath = path.resolve(process.cwd(), CONFIG_FILE_PATH);

  try {
    const fileContents = await fs.readFile(configPath, 'utf8');
    return ConfigObject.parse(JSON.parse(fileContents));
  } catch (e) {}
};

export const logAndExit = (message: any, code = 1) => {
  console.log(message);
  process.exit(code);
};

import { z } from 'zod';

export type DB = Record<string, DBEntry>;

export interface DBEntry {
  name: string;
  deps: string[];
  color?: string;
  body: string;
  meta: z.infer<typeof ModuleMetaObject>;
}

export const ModuleMetaObject = z.object({
  title: z.string().optional(),
  deps: z.array(z.string()).optional().default([]),
  group: z.string().optional(),
});

export const ConfigObject = z.object({
  groups: z
    .array(
      z.object({
        id: z.string(),
        color: z.string(),
      }),
    )
    .optional()
    .default([]),
});

export type Config = z.infer<typeof ConfigObject>;

import { watch } from 'chokidar';

/**
 * @internal
 */
export const chokidarGlob = (glob: string) =>
  new Promise<string[]>((resolve) => {
    const paths: string[] = [];
    const watcher = watch(glob).on('add', (path) => {
      paths.push(path);
    });

    watcher.on('ready', async () => {
      await watcher.close();
      resolve(paths);
    });
  });

#!/usr/bin/env node

import { Command } from 'commander';
import { version } from '../package.json';
import { getDotfile } from './dotfile';
import { getConfig } from './getConfig';
import { getContentGraph } from './getContentGraph';
import { getPathTo, getPathToMany } from './getPathTo';
import { logAndExit } from './logAndExit';
import * as path from 'path';
import { startServer } from './startServer';

const program = new Command();

program.version(version);

